#include <bits/stdc++.h>
using namespace std;

int lower_bound_pos(const vector<long long>& a, long long target) {
    int l = 0;
    int r = static_cast<int>(a.size());

while (l < r) {
    int mid = l + (r - l) / 2;
    if (a[mid] < target) {
        l = mid + 1;
    } else {
        r = mid;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n);
    for (long long& value : a) {
        cin >> value;
    }
    for (int query = 0; query < q; ++query) {
        long long target;
        cin >> target;
        int position = lower_bound_pos(a, target);
        bool found = position < n && a[position] == target;
        cout << position << ' ' << found << '\n';
    }
}

